ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns urn urn:ETB_Update_INC_SF_ESTADO
---
{
    soapenv#Envelope: {
        soapenv#Header: {
            urn#AuthenticationInfo: {
                urn#userName: p('mdm-remedy.credentials.user'),
                urn#password: p('mdm-remedy.credentials.password')
            }
        },
        soapenv#Body: {
            urn#Update_Edo_SF_RMD: {
                urn#ACCION_UPD_EDO: if (!isEmpty(payload.accion_upd_edo)) payload.accion_upd_edo else p('mdm-remedy.updateEntIncidentStatus.actionUpdEdo'),
                urn#IN_NRO_INCIDENCIA: vars.incidenceId,
                urn#IN_ID_SALESFORCE: vars.salesforceId,
                urn#IN_ESTADO: vars.status,
                (urn#IN_SUB_EDO: payload.sub_edo) if (!isEmpty(payload.sub_edo)),
                (urn#IN_NIVEL_1: payload.nivel_1) if (!isEmpty(payload.nivel_1)),
                (urn#IN_NIVEL_2: payload.nivel_2) if (!isEmpty(payload.nivel_2)),
                (urn#IN_NIVEL_3: payload.nivel_3) if (!isEmpty(payload.nivel_3)),
                (urn#IN_NIVEL_4: payload.nivel_4) if (!isEmpty(payload.nivel_4)),
                (urn#IN_NIVEL_5: payload.nivel_5) if (!isEmpty(payload.nivel_5)),
                (urn#IN_SOLUCION: payload.solucion) if (!isEmpty(payload.solucion)),
                (urn#IN_COD_CIERRE: payload.cod_cierre) if (!isEmpty(payload.cod_cierre)),
                (urn#IN_RESPONSABLE: payload.responsable) if (!isEmpty(payload.responsable)),
                (urn#IN_SUBRESPONSABLE: payload.subresponsable) if (!isEmpty(payload.subresponsable)),
                (urn#IN_PERTINENCIA_HORAS: payload.pertinencia_horas) if (!isEmpty(payload.pertinencia_horas)),
                (urn#IN_PERTINENCIA_MINUTOS: payload.pertinencia_minutos) if (!isEmpty(payload.pertinencia_minutos)),
                (urn#IN_PERTINENCIA_SEGUNDOS: payload.pertinencia_segundos) if (!isEmpty(payload.pertinencia_segundos)),
                (urn#IN_FECHA_SOLUCION: payload.fecha_solucion) if (!isEmpty(payload.fecha_solucion)),
                (urn#IN_FECHA_FIN_AFECTACION: payload.fecha_fin_afectacion) if (!isEmpty(payload.fecha_fin_afectacion))
            }
        }
    }
}
